Reason:
`netfs_limit_iter()` only handles `ITER_FOLIOQ`, `ITER_BVEC`, and `ITER_XARRAY` iterator types. When a core dump write to a 9P filesystem uses an `ITER_KVEC` iterator (via `__kernel_write()`), none of the conditions match and the function reaches the `BUG()` statement, triggering a kernel panic.

The code statements that fix the bug are:
```c
if (iov_iter_is_kvec(iter))
	return netfs_limit_kvec(iter, start_offset, max_size, max_segs);
```
and the new helper function:
```c
static size_t netfs_limit_kvec(const struct iov_iter *iter, size_t start_offset,
			       size_t max_size, size_t max_segs)
{
	const struct kvec *kvecs = iter->kvec;
	unsigned int nkv = iter->nr_segs, ix = 0, nsegs = 0;
	size_t len, span = 0, n = iter->count;
	size_t skip = iter->iov_offset + start_offset;

	if (WARN_ON(!iov_iter_is_kvec(iter)) ||
	    WARN_ON(start_offset > n) ||
	    n == 0)
		return 0;

	while (n && ix < nkv && skip) {
		len = kvecs[ix].iov_len;
		if (skip < len)
			break;
		skip -= len;
		n -= len;
		ix++;
	}

	while (n && ix < nkv) {
		len = min3(n, kvecs[ix].iov_len - skip, max_size);
		span += len;
		nsegs++;
		ix++;
		if (span >= max_size || nsegs >= max_segs)
			break;
		skip = 0;
		n -= len;
	}

	return min(span, max_size);
}
```
